<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cierre mensual — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:82px 14px 32px}h1{margin:0}.sub{color:#64748b;margin:6px 0 18px}.bar,.card{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:14px;box-shadow:0 5px 18px #0f172a0d}.bar{display:flex;gap:8px;margin-bottom:12px}.bar input,.bar button,textarea{font:inherit;padding:11px;border:1px solid #cbd5e1;border-radius:10px}.bar input{flex:1}.bar button,.close,.save{background:#172033;color:#fff;font-weight:900;border:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.box{background:#f8fafc;border-radius:12px;padding:12px}.k{font-size:10px;color:#64748b;text-transform:uppercase;font-weight:900}.v{font-size:22px;font-weight:900;margin-top:4px}.range{margin-bottom:14px;padding:13px;border:1px solid #dbe4ec;border-radius:12px;background:#f8fafc}.range-head{display:flex;justify-content:space-between;gap:10px;align-items:end}.range strong{display:block;font-size:16px;margin-top:3px}.range small{color:#64748b}.range-edit{display:flex;gap:8px;margin-top:10px;align-items:end}.range-edit label{flex:1;font-size:12px;font-weight:800;color:#526174}.range-edit input{width:100%;margin-top:4px;padding:10px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.save{padding:10px 13px;border-radius:9px}.note{margin-top:14px}.note textarea{width:100%;min-height:80px}.close{width:100%;padding:12px;border-radius:11px;margin-top:9px}.closed{padding:13px;border-radius:12px;background:#dcfce7;color:#166534;font-weight:800;margin-top:12px}.warn{font-size:12px;color:#92400e;margin-top:9px}.msg{min-height:20px;margin-top:8px;font-size:12px;font-weight:800}.ok{color:#166534}.err{color:#b42318}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}.bar,.range-head,.range-edit{flex-wrap:wrap}.bar input,.bar button,.range-edit label,.save{flex:1 1 100%}}</style></head><body><main class="wrap"><h1>Cierre mensual</h1><div class="sub">Define el periodo financiero y congela una fotografía histórica del mes.</div><div class="bar"><input id="p" type="month"><button id="ver">Revisar</button></div><section class="card"><div id="c">Cargando…</div></section></main><script>
const p=document.getElementById('p'),c=document.getElementById('c');p.value=new Date().toISOString().slice(0,7);
const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'}),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const dateMx=s=>{if(!s)return '';const [y,m,d]=s.split('-');return `${d}/${m}/${y}`};
async function load(){const r=await fetch('/api/cierres-mensuales.php?periodo='+p.value,{cache:'no-store'}),d=await r.json();if(!d.ok){c.textContent=d.error;return}const x=d.actual,rg=x.rango,locked=!!d.cierre;c.innerHTML=`<div class="range"><div class="range-head"><div><div class="k">Periodo financiero</div><strong>${dateMx(rg.inicio)} → ${dateMx(rg.cierre)}</strong><small>${rg.personalizado?'Rango personalizado':'Mes calendario'}</small></div></div>${locked?'':`<div class="range-edit"><label>Fecha de cierre<input id="fc" type="date" value="${esc(rg.cierre)}"></label><button id="guardar-rango" class="save">Guardar fecha de cierre</button></div><div id="rm" class="msg"></div>`}</div><div class="grid"><div class="box"><div class="k">Total cobrado</div><div class="v">${money(x.total)}</div></div><div class="box"><div class="k">Hache</div><div class="v">${money(x.hache)}</div></div><div class="box"><div class="k">PROA</div><div class="v">${money(x.proa)}</div></div><div class="box"><div class="k">Mensualidades</div><div class="v">${money(x.mensualidades)}</div></div><div class="box"><div class="k">Inscripciones</div><div class="v">${money(x.inscripciones)}</div></div><div class="box"><div class="k">Intensivos</div><div class="v">${money(x.intensivos)}</div></div></div>${d.cierre?`<div class="closed">Mes cerrado el ${esc(d.cierre.cerrado_at)} por ${esc(d.cierre.cerrado_por_usuario)} ✓</div>`:`<div class="note"><textarea id="obs" placeholder="Observación opcional del cierre"></textarea><button id="cerrar" class="close">Cerrar ${p.value}</button><div class="warn">Al cerrar, el rango y los totales quedan congelados para este periodo.</div></div>`}`;
const g=document.getElementById('guardar-rango');if(g)g.onclick=async()=>{const m=document.getElementById('rm');m.className='msg';m.textContent='Guardando…';try{const rr=await fetch('/api/cierres-mensuales.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'PERIODO',periodo:p.value,fecha_cierre:document.getElementById('fc').value})}),dd=await rr.json();if(!rr.ok||!dd.ok)throw new Error(dd.error||'No se pudo guardar');m.className='msg ok';m.textContent='Periodo actualizado.';await load()}catch(e){m.className='msg err';m.textContent=e.message}};
const b=document.getElementById('cerrar');if(b)b.onclick=async()=>{if(!confirm('¿Cerrar definitivamente este mes?'))return;const rr=await fetch('/api/cierres-mensuales.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'CERRAR',periodo:p.value,observacion:document.getElementById('obs').value})}),dd=await rr.json();if(!dd.ok){alert(dd.error);return}load()}}
document.getElementById('ver').onclick=load;p.onchange=load;load();
</script></body></html>
